17	
18	#include <map>
19	#include "lock.h"
20	
21	namespace Ops {
22	namespace NN {
23	namespace HostTiling {
24	
25	constexpr uint32_t kMaxTilingCacheEntryNum = 500;
26	
27	template <typename HashInput, typename HashItem>
28	class TilingCache {
29	public:
30	    void Add(uint32_t key, const HashInput& hash_input, const HashItem& value)
31	    {
32	        rwlock_.wrlock();
33	        if (size_ >= kMaxTilingCacheEntryNum) {
34	            rwlock_.unlock();
35	            return;
36	        }
37	
38	        if (map_.find(key) != map_.end()) {
39	            rwlock_.unlock();
40	            return;
41	        }
42	
43	        map_.emplace(key, value);
44	        size_++;
45	        rwlock_.unlock();
46	        return;
47	    }
48	
49	    void Replace(uint32_t key, const HashInput& hash_input, const HashItem& value)
50	    {
51	        rwlock_.wrlock();
52	        if (size_ >= kMaxTilingCacheEntryNum) {
53	            rwlock_.unlock();
54	            return;
55	        }
56	
57	        if (map_.find(key) == map_.end()) {
58	            size_++;
59	        }
60	        map_.erase(key);
61	        map_.emplace(key, value);
62	        rwlock_.unlock();
63	        return;
64	    }
65	
66	    bool Get(uint32_t key, const HashInput& hash_input, HashItem& value)
67	    {
68	        rwlock_.rdlock();
69	        auto iter = map_.find(key);
70	        if (iter == map_.end()) {
71	            rwlock_.unlock();
72	            return false;
73	        }
74	        if (!(hash_input == iter->second.input())) {
75	            rwlock_.unlock();
76	            OP_LOGD("CUBE", "inconsistent input data");
77	            return false;
78	        }
79	
80	        value = iter->second;
81	        rwlock_.unlock();
82	        return true;
83	    }
84	
85	private:
86	    std::map<uint32_t, HashItem> map_;
87	    uint32_t size_ = 0;
88	    Ops::NN::HostTiling::RWLock rwlock_;
89	};
