30	
31	namespace Ops {
32	namespace NN {
33	namespace Optiling {
34	
35	struct AiCoreParams {
36	    uint64_t ubSize = 0UL;
37	    uint64_t blockDim = 0UL;
38	    uint64_t numBlocks = 0UL;
39	    uint64_t aicNum = 0UL;
40	    uint64_t l1Size = 0UL;
41	    uint64_t l0aSize = 0UL;
42	    uint64_t l0bSize = 0UL;
43	    uint64_t l0cSize = 0UL;
