48	    uint32_t aicNum;
49	    uint64_t ubSize;
50	    uint64_t l1Size;
51	    uint64_t l0aSize;
52	    uint64_t l0bSize;
53	    uint64_t l0cSize;
54	    uint64_t l2CacheSize;
55	    int64_t coreNum;
56	    int32_t socVersion;
57	    uint32_t rsvd;
58	};
59	
60	class TilingBaseClass {
61	public:
62	    explicit TilingBaseClass(gert::TilingContext* context) : context_(context) {}
63	
64	    virtual ~TilingBaseClass() = default;
65	
66	    // Tiling执行框架
67	    //     1、GRAPH_SUCCESS: 成功，并且不需要继续执行后续Tiling类的实现
68	    //     2、GRAPH_FAILED: 失败，中止整个Tiling流程
69	    //     3、GRAPH_PARAM_INVALID: 本类不支持，需要继续往下执行其他Tiling类的实现
70	    ge::graphStatus DoTiling()
71	    {
72	        auto ret = GetShapeAttrsInfo();
73	        if (ret != ge::GRAPH_SUCCESS) {
74	            return ret;
75	        }
76	        ret = GetPlatformInfo();
77	        if (ret != ge::GRAPH_SUCCESS) {
78	            return ret;
79	        }
80	        if (!IsCapable()) {
81	            return ge::GRAPH_PARAM_INVALID;
82	        }
83	        ret = DoOpTiling();
84	        if (ret != ge::GRAPH_SUCCESS) {
85	            return ret;
86	        }
87	        ret = DoLibApiTiling();
88	        if (ret != ge::GRAPH_SUCCESS) {
89	            return ret;
90	        }
91	        ret = GetWorkspaceSize();
92	        if (ret != ge::GRAPH_SUCCESS) {
93	            return ret;
94	        }
95	        ret = PostTiling();
96	        if (ret != ge::GRAPH_SUCCESS) {
97	            return ret;
98	        }
99	        context_->SetTilingKey(GetTilingKey());
100	        DumpTilingInfo();
101	        return ge::GRAPH_SUCCESS;
102	    }
103	
104	    // 更新 context
105	    virtual void Reset(gert::TilingContext* context) { context_ = context; }
106	
107	protected:
108	    virtual bool IsCapable() = 0;
109	    // 1、获取平台信息比如CoreNum、UB/L1/L0C资源大小
110	    virtual ge::graphStatus GetPlatformInfo() = 0;
111	    // 2、获取INPUT/OUTPUT/ATTR信息
112	    virtual ge::graphStatus GetShapeAttrsInfo() = 0;
113	    // 3、计算数据切分TilingData
114	    virtual ge::graphStatus DoOpTiling() = 0;
115	    // 4、计算高阶API的TilingData
116	    virtual ge::graphStatus DoLibApiTiling() = 0;
117	    // 5、计算TilingKey
118	    [[nodiscard]] virtual uint64_t GetTilingKey() const = 0;
119	    // 6、计算Workspace 大小
120	    virtual ge::graphStatus GetWorkspaceSize() = 0;
121	    // 7、保存Tiling数据
122	    virtual ge::graphStatus PostTiling() = 0;
123	    // 8、Dump Tiling数据
124	    virtual void DumpTilingInfo() { OP_LOGD(context_, "%ld", DefaultTilingInfoDump()); }
125	
126	    int64_t DefaultTilingInfoDump()
127	    {
128	        auto buf = (uint32_t*)context_->GetRawTilingData()->GetData();
129	        auto bufLen = context_->GetRawTilingData()->GetDataSize();
130	        std::ostringstream oss;
131	        oss << "Start to dump tiling info. tilingkey:" << context_->GetTilingKey() << ", tiling data size:" << bufLen
132	            << ", content:";
133	        for (size_t i = 0; i < bufLen / sizeof(uint32_t); i++) {
134	            oss << *(buf + i) << ",";
135	            if (oss.str().length() > 640) { // Split according to 640 to avoid truncation
136	                OP_LOGD(context_, "%s", oss.str().c_str());
137	                oss.str("");
138	            }
139	        }
140	        OP_LOGD(context_, "%s", oss.str().c_str());
141	        return 0;
142	    }
143	
144	    static uint32_t CalcTschBlockDim(uint32_t sliceNum, uint32_t aicCoreNum, uint32_t aivCoreNum)
145	    {
146	        uint32_t ration;
147	        if (aicCoreNum == 0 || aivCoreNum == 0 || aicCoreNum > aivCoreNum) {
148	            return sliceNum;
149	        }
150	        ration = aivCoreNum / aicCoreNum;
151	        return (sliceNum + (ration - 1)) / ration;
152	    }
153	
154	    template <typename T>
155	    [[nodiscard]] std::string GetShapeDebugStr(const T& shape) const
156	    {
157	        std::ostringstream oss;
158	        oss << "[";
159	        if (shape.GetDimNum() > 0) {
160	            for (size_t i = 0; i < shape.GetDimNum() - 1; ++i) {
161	                oss << shape.GetDim(i) << ", ";
162	            }
163	            oss << shape.GetDim(shape.GetDimNum() - 1);
164	        }
165	        oss << "]";
166	        return oss.str();
167	    }
168	
169	    [[nodiscard]] std::string GetTensorDebugStr(const gert::StorageShape* shape,
170	                                                const gert::CompileTimeTensorDesc* tensor) const
171	    {
172	        if (shape == nullptr || tensor == nullptr) {
173	            return "nil ";
174	        }
175	        std::ostringstream oss;
176	        oss << "(dtype: " << ge::TypeUtils::DataTypeToSerialString(tensor->GetDataType()) << "),";
177	        oss << "(shape:" << GetShapeDebugStr(shape->GetStorageShape()) << "),";
178	        oss << "(ori_shape:" << GetShapeDebugStr(shape->GetOriginShape()) << "),";
179	        oss << "(format: "
180	            << ge::TypeUtils::FormatToSerialString(
181	                   static_cast<ge::Format>(ge::GetPrimaryFormat(tensor->GetStorageFormat())))
182	            << "),";
183	        oss << "(ori_format: " << ge::TypeUtils::FormatToSerialString(tensor->GetOriginFormat()) << ") ";
184	        return oss.str();
185	    }
186	
187	    [[nodiscard]] std::string GetTilingContextDebugStr()
188	    {
189	        std::ostringstream oss;
190	        for (size_t i = 0; i < context_->GetComputeNodeInfo()->GetInputsNum(); ++i) {
191	            oss << "input" << i << ": ";
192	            oss << GetTensorDebugStr(context_->GetInputShape(i), context_->GetInputDesc(i));
193	        }
194	
195	        for (size_t i = 0; i < context_->GetComputeNodeInfo()->GetOutputsNum(); ++i) {
196	            oss << "output" << i << ": ";
197	            oss << GetTensorDebugStr(context_->GetOutputShape(i), context_->GetOutputDesc(i));
198	        }
199	        return oss.str();
200	    }
201	
202	    [[nodiscard]] std::string GetTilingDataDebugStr() const
203	    {
204	        auto rawTilingData = context_->GetRawTilingData();
205	        auto rawTilingDataSize = rawTilingData->GetDataSize();
206	        auto data = reinterpret_cast<const int32_t*>(rawTilingData->GetData());
207	        size_t len = rawTilingDataSize / sizeof(int32_t);
208	        std::ostringstream oss;
209	        for (size_t i = 0; i < len; i++) {
210	            oss << data[i] << ", ";
211	        }
212	        return oss.str();
213	    }
214	
215	protected:
216	    gert::TilingContext* context_ = nullptr;
217	    std::unique_ptr<platform_ascendc::PlatformAscendC> ascendcPlatform_{nullptr};
218	    uint32_t blockDim_{0};
219	    uint64_t workspaceSize_{0};
220	    uint64_t tilingKey_{0};
221	    AiCoreParams aicoreParams_;
222	};
223	
224	} // namespace Optiling
225	} // namespace NN
226	} // namespace Ops

