28	namespace optiling {
29	using Ops::NN::Optiling::TilingRegistry;
30	
31	constexpr int32_t BASIC_PERBLOCK_PRIORITY = 0;
32	constexpr int32_t REG_BASE_PRIORITY = 1;
33	constexpr int32_t MSD_PRIORITY = 2;
34	constexpr int32_t PERBLOCK_PRIORITY = 3;
35	constexpr int32_t PERGROUP_PRIORITY = 4;
36	constexpr int32_t LUT_PRIORITY = 5;
37	constexpr int32_t PERGROUP_ARCH35_PRIORITY = 6;
38	constexpr int32_t WEIGHT_QUANT_MX_SWAT_PRIORITY = 7;
39	
40	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", AdaptiveSlidingWindowBasicTilingV4, BASIC_PERBLOCK_PRIORITY);
41	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", QuantBatchMatmulV4RegBase, REG_BASE_PRIORITY);
42	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", QuantBatchMatmulV4MsdTiling, MSD_PRIORITY);
43	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", QuantBatchMatmulV4PerblockTiling, PERBLOCK_PRIORITY);
44	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", QuantBatchMatmulV4PergroupTiling, PERGROUP_PRIORITY);
45	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", AdaptiveSlidingWindowTilingV4, LUT_PRIORITY);
46	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", QuantBatchMatmulV4PergroupArch35Tiling, PERGROUP_ARCH35_PRIORITY);
47	REGISTER_TILING_TEMPLATE("QuantBatchMatmulV4", QuantBatchMatmulV4WeightQuantMxSwatTiling,
48	                         WEIGHT_QUANT_MX_SWAT_PRIORITY);
49	
50	ge::graphStatus QuantBatchMatmulV4TilingFunc(gert::TilingContext* context)
51	{
52	    platform_ascendc::SocVersion socVersion;
53	    bool supportMmadS8S4 = false;
54	    OP_LOGE_IF(context == nullptr, ge::GRAPH_FAILED, "QuantBatchMatmulV4", "tilingContext is null");
55	    auto compileInfoPtr = reinterpret_cast<const QuantBatchMatmulV4CompileInfo*>(context->GetCompileInfo());
56	    if (compileInfoPtr == nullptr) {
57	        auto platformInfoPtr = context->GetPlatformInfo();
58	        OP_LOGE_IF(platformInfoPtr == nullptr, ge::GRAPH_FAILED, context->GetNodeName(), "platformInfoPtr is null");
59	        auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
60	        socVersion = ascendcPlatform.GetSocVersion();
61	        std::string mmad;
62	        (void)platformInfoPtr->GetPlatformRes("AICoreintrinsicDtypeMap", "Intrinsic_mmad", mmad);
63	        supportMmadS8S4 = mmad.find("s8s4") != std::string::npos;
64	    } else {
65	        socVersion = compileInfoPtr->socVersion;
66	        supportMmadS8S4 = compileInfoPtr->supportMmadS8S4;
67	    }
68	    if (socVersion == platform_ascendc::SocVersion::ASCEND910B ||
69	        socVersion == platform_ascendc::SocVersion::ASCEND910_93 ||
70	        socVersion == platform_ascendc::SocVersion::KIRINX90) {
71	        std::vector<int32_t> regitserList = {MSD_PRIORITY, PERBLOCK_PRIORITY, PERGROUP_PRIORITY};
72	        return TilingRegistry::GetInstance().DoTilingImpl(context, regitserList);
73	    } else if (supportMmadS8S4) {
74	        vector<int32_t> regitserList = {LUT_PRIORITY};
75	        return TilingRegistry::GetInstance().DoTilingImpl(context, regitserList);
76	    }
77	    std::vector<int32_t> registerList = {BASIC_PERBLOCK_PRIORITY, PERGROUP_ARCH35_PRIORITY,
78	                                         WEIGHT_QUANT_MX_SWAT_PRIORITY, REG_BASE_PRIORITY};
79	    return TilingRegistry::GetInstance().DoTilingImpl(context, registerList);
80	}
81	
82	ge::graphStatus TilingParseForQuantBatchMatmulV4(gert::TilingParseContext* context)
83	{
84	    OP_LOGE_IF(context == nullptr, ge::GRAPH_FAILED, "QuantBatchMatmulV4", "TilingParseContext is null");
85	    auto platformInfoPtr = context->GetPlatformInfo();
86	    // 在tilingParse获取不到GetPlatformInfo时，返回成功。会在之后的InitCompileInfo阶段设置compileInfo信息。
87	    OP_LOGE_IF(platformInfoPtr == nullptr, ge::GRAPH_SUCCESS, context->GetNodeName(), "platformInfoPtr is null");
88	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
89	    auto compileInfoPtr = context->GetCompiledInfo<QuantBatchMatmulV4CompileInfo>();
90	    OP_LOGE_IF(compileInfoPtr == nullptr, ge::GRAPH_FAILED, context->GetNodeName(), "compileInfoPtr is null");
91	
92	    compileInfoPtr->aivNum = ascendcPlatform.GetCoreNumAiv();
93	    compileInfoPtr->aicNum = ascendcPlatform.GetCoreNumAic();
94	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, compileInfoPtr->ubSize);
95	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L1, compileInfoPtr->l1Size);
96	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_C, compileInfoPtr->l0cSize);
97	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_A, compileInfoPtr->l0aSize);
98	    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::L0_B, compileInfoPtr->l0bSize);
99	    compileInfoPtr->workspaceNum = ascendcPlatform.GetLibApiWorkSpaceSize();
100	
101	    std::string val;
102	    (void)platformInfoPtr->GetPlatformRes("AICoreintrinsicDtypeMap", "Intrinsic_fix_pipe_l0c2out", val);
103	    compileInfoPtr->supportL0c2Out = !val.empty();
104	
105	    std::string dataMoveL12Bt;
106	    (void)platformInfoPtr->GetPlatformRes("AICoreintrinsicDtypeMap", "Intrinsic_data_move_l12bt", dataMoveL12Bt);
107	    compileInfoPtr->supportL12BtBf16 = dataMoveL12Bt.find("bf16") != string::npos;
108	
109	    std::string mmad;
110	    (void)platformInfoPtr->GetPlatformRes("AICoreintrinsicDtypeMap", "Intrinsic_mmad", mmad);
111	    compileInfoPtr->supportMmadS8S4 = mmad.find("s8s4") != std::string::npos;
112	
113	    compileInfoPtr->socVersion = ascendcPlatform.GetSocVersion();
114	
115	    return ge::GRAPH_SUCCESS;
116	}
